/*
 * A040626  Continued fraction for sqrt(652).
 * https://oeis.org/A040626
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, easy, less
 * Formula:   not stated
 * Range:     u8 none, u16 n <= 88, u32 n <= 88, u64 n <= 88, u128 n <= 88,
 *            big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 * Formula: a(n) is the n-th term in the continued fraction expansion of sqrt(652);
 * a(0) = 25, and the subsequent terms are generated by the standard continued
 * fraction algorithm for a square root. The sequence is periodic after a(0),
 * with period length 36.
 */
#include <stdbool.h>
#include <stdlib.h>
#include "../utils/floor_sqrt.h"

seq_t a(idx_t n)
{
    /* static state for memoization */
    static bool initialized = false;
    static seq_t a0 = 0;
    static seq_t *cycle = NULL;
    static size_t period_len = 0;

    if (!initialized)
    {
        const seq_t D = 652;
        a0 = floor_sqrt(D);

        /* initial continued fraction iteration variables */
        seq_t m = 0;
        seq_t d = 1;
        seq_t a_prev = a0;

        size_t capacity = 16;
        cycle = (seq_t *)malloc(capacity * sizeof(seq_t));
        period_len = 0;

        while (1)
        {
            /* m_next = d*a_prev - m */
            seq_t m_next = d * a_prev - m;

            /* d_next = (D - m_next^2) / d */
            seq_t d_next = (D - m_next * m_next) / d;

            /* a_next = floor((a0 + m_next) / d_next) */
            seq_t a_next = (a0 + m_next) / d_next;

            /* store the term */
            if (period_len >= capacity)
            {
                capacity *= 2;
                cycle = (seq_t *)realloc(cycle, capacity * sizeof(seq_t));
            }
            cycle[period_len++] = a_next;

            /* stop when the repeating term 2*a0 is reached */
            if (a_next == (seq_t)(2 * a0))
                break;

            /* prepare for next iteration */
            m = m_next;
            d = d_next;
            a_prev = a_next;
        }

        initialized = true;
    }

    if (n == 0)
        return a0;
    /* map index to cycle with wrap‑around */
    idx_t rem = (n - 1) % (idx_t)period_len;
    return cycle[(size_t)rem];
}
